path box=(0,0)--(1,0)--(1,1.5)--(0,1.5)--cycle;
draw(box);
draw(shift(1.5,0)*box);
draw(shift(3,0)*box);
label("44", (0.5, .75));
label("59", (2, .75));
label("38", (3.5, .75));
[/asy]

